import { Menubar, Menu } from '@mantine/core';
import { IconMenu2 } from '@tabler/icons-react';
import styles from './burguer.module.css';
interface BurguerProps {
  routes: { name: string; href: string }[];
}
const BurguerMenu = ({ routes }: BurguerProps) => {
  return (
    <div className={styles['burguer-menu']}>
      <Menubar trigger="click">
        <Menubar.Menu width={220}>
          <Menubar.Target color="transparent">
            <div>
              <IconMenu2 />
            </div>
          </Menubar.Target>
          <Menubar.Dropdown>
            {routes.map((route) => (
              <Menu.Item key={route.name} component="a" href={route.href}>
                {route.name}
              </Menu.Item>
            ))}
          </Menubar.Dropdown>
        </Menubar.Menu>
      </Menubar>
    </div>
  );
};
export default BurguerMenu;
